import pandas as pd,numpy as np,glob,time
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_fault_op1.csv','train/A_gentrip_op1.csv']
D={f:pd.read_csv(f).iloc[::5].reset_index(drop=True) for f in files}
def simQ(p,d):
    a,b,c,Tl,Tq=p
    t=d.time_s.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values
    Q0,V0=d.reactive_power_pu.values[0],V[0]
    n=len(t); Q=np.empty(n); x=0.0; Qf=Q0
    for k in range(n):
        Q[k]=Qf
        if k<n-1:
            h=t[k+1]-t[k]
            Qraw=Q0+a*(Vs[k]-V0)-b*(V[k]-V0)+x
            x+=h*(c*(Vs[k]-V[k])-x)/Tl
            Qf+=h*(Qraw-Qf)/Tq
    return Q
def res(p):
    return np.concatenate([simQ(p,D[f])-D[f].reactive_power_pu.values for f in files])
best=None
for p0 in [[2.5,0.5,5,1,0.02],[2.5,1.5,20,0.3,0.05],[4,0.0,1,5,0.01],[2,1,50,0.1,0.1]]:
    r=least_squares(res,p0,bounds=([-10,-10,-200,0.01,0.005],[20,20,200,200,5]),max_nfev=60)
    rms=np.sqrt(np.mean(r.fun**2)); print(r.x.round(4),rms.round(5))
    if best is None or rms<best[1]: best=(r.x,rms)
np.save('pQ.npy',best[0])
for f in files: print(f, np.sqrt(np.mean((simQ(best[0],D[f])-D[f].reactive_power_pu.values)**2)).round(5))

