files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_fault_op1.csv','train/A_gentrip_op1.csv']
D={f:pd.read_csv(f).iloc[::5].reset_index(drop=True) for f in files}
def simQ(p,d):
    a,b,c,Tl,T1,T2,g=p
    t=d.time_s.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values
    Q0,V0=d.reactive_power_pu.values[0],V[0]
    n=len(t); Q=np.empty(n); x=0.0; y1=0.0; y2=0.0
    for k in range(n):
        Q[k]=Q0+a*(Vs[k]-V0)-b*(V[k]-V0)+x+g*y2
        if k<n-1:
            h=t[k+1]-t[k]
            e=Vs[k]-V[k]
            x+=h*(c*e-x)/Tl
            y1+=h*(e-y1)/T1
            y2+=h*(y1-y2)/T2
    return Q
def res(p):
    return np.nan_to_num(np.concatenate([simQ(p,D[f])-D[f].reactive_power_pu.values for f in files]),nan=1e3)
