import pandas as pd,numpy as np,glob,time
from scipy.optimize import least_squares
files=sorted(glob.glob('train/*.csv'))
D={f:pd.read_csv(f).iloc[::5].reset_index(drop=True) for f in files}
def simQ(p,d):
    A,B,Kw,T1,T2=p
    t=d.time_s.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; th=d.bus_angle_rad.values
    Q0,V0,th0=d.reactive_power_pu.values[0],V[0],th[0]
    n=len(t); Q=np.empty(n); y1=Q0; y2=Q0; xw=th[0]
    for k in range(n):
        Q[k]=y2
        if k<n-1:
            h=t[k+1]-t[k]
            w=(th[k]-xw)/0.02    # freq proxy (rad/s), high-pass
            xw+=h*(th[k]-xw)/0.02
            u=Q0+A*(Vs[k]-V0)-B*(V[k]-V0)+Kw*w
            y1+=h*(u-y1)/T1
            y2+=h*(y1-y2)/T2
    return Q
def res(p):
    return np.nan_to_num(np.concatenate([simQ(p,D[f])-D[f].reactive_power_pu.values for f in files]),nan=1e3)
best=None
for p0 in [[3,1,0,0.05,0.1],[5,-1,0,0.2,0.2],[2,2,-1,0.02,0.05]]:
    r=least_squares(res,p0,bounds=([-20,-20,-200,0.005,0.005],[20,20,200,5,5]),max_nfev=60)
    rms=np.sqrt(np.mean(r.fun**2)); print(r.x.round(4),rms.round(5))
    if best is None or rms<best[1]: best=(r.x,rms)
np.save('pQL.npy',best[0])
for f in files: print(f, np.sqrt(np.mean((simQ(best[0],D[f])-D[f].reactive_power_pu.values)**2)).round(5))

